mapper.select:
select AA.portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioNamep, PTL_PORTFOLIO.PROFIT_TYPE profitType, PTL_PORTFOLIO.MDATE mdatep, fin_product_type.type_8 type8, fin_product.FINPROD_MARKET_ID finprodId, fin_product.FINPROD_ABBR finprodAbbr, fin_product.MDATE mdate, fin_product.CCY assetCcy, AA.invAim, decode(fin_product_type.type_8,'F01',AA.amount*100,AA.amount) amountp, CC.shareAmt, EE.portfolioName, BB.dscCostAmt/BB.shareAmt price, BB.tdyIntincexp, BB.yield * 100 as yield, BB.exerYield * 100 as exerYield from ( select * from (select PTL_SEC_POSITION.PORTFOLIO_ID portfolioId, PTL_SEC_POSITION.FINPROD_ID finprodId, decode(PTL_SEC_POSITION.INV_AIM,'999999','',PTL_SEC_POSITION.INV_AIM) invAim, sum(PTL_SEC_POSITION.AMOUNT) amount from PTL_SEC_POSITION where PTL_SEC_POSITION.CDATE = to_date(#{cdate},'yyyy-MM-dd') and PTL_SEC_POSITION.HODING_TYPE = '03'
and PTL_SEC_POSITION.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and PTL_SEC_POSITION.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and PTL_SEC_POSITION.PORTFOLIO_ID not in
#{item}
and PTL_SEC_POSITION.FINPROD_ID not in
#{item}
group by PTL_SEC_POSITION.PORTFOLIO_ID,PTL_SEC_POSITION.FINPROD_ID,PTL_SEC_POSITION.INV_AIM)pp where pp.amount > 0 ) AA inner join PTL_PORTFOLIO on AA.portfolioId = PTL_PORTFOLIO.PORTFOLIO_ID inner join fin_product on AA.finprodId = fin_product.FINPROD_ID inner join fin_product_type on fin_product.FINPROD_ID = fin_product_type.FINPROD_ID inner join (select PTL_SEC_VALUTION.PORTFOLIO_ID portfolioId, PTL_SEC_VALUTION.FINPROD_ID finprodId, PTL_SEC_VALUTION.INV_AIM invAim, max(PTL_SEC_VALUTION.DSC_COST_AMT) dscCostAmt, max(PTL_SEC_VALUTION.SHARE_AMT) shareAmt, max(PTL_SEC_VALUTION.TDY_INTINCEXP) tdyIntincexp, max(PTL_SEC_VALUTION.YIELD) yield, max(PTL_SEC_VALUTION.EXER_YIELD) exerYield from PTL_SEC_VALUTION where PTL_SEC_VALUTION.CDATE = (select max(T.CDATE) from PTL_SEC_VALUTION T where T.PORTFOLIO_ID = PTL_SEC_VALUTION.PORTFOLIO_ID and T.CDATE < to_date(#{cdate},'yyyy-MM-dd') ) and ptl_sec_valution.share_amt > 0
and PTL_SEC_VALUTION.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and PTL_SEC_VALUTION.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
group by PTL_SEC_VALUTION.PORTFOLIO_ID,PTL_SEC_VALUTION.FINPROD_ID,PTL_SEC_VALUTION.INV_AIM ) BB on AA.portfolioId = BB.portfolioId and AA.finprodid = BB.finprodid left join (select MOCK_PRODUCT_DEAL.FINPROD_ID finprodId, sum(MOCK_PRODUCT_DEAL.SHARE_AMT) shareAmt from MOCK_PRODUCT_DEAL inner join MOCK_TEST on MOCK_PRODUCT_DEAL.MOCK_ID = MOCK_TEST.MOCK_ID where 1=1
and MOCK_PRODUCT_DEAL.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
group by MOCK_PRODUCT_DEAL.FINPROD_ID ) CC on AA.finprodId = CC.finprodId left join (select DD.FINPROD_ID finprodId, listagg(DD.PORTFOLIO_NAME, ',') within group (order by DD.PORTFOLIO_NAME) portfolioName from (select distinct MOCK_PRODUCT_DEAL.FINPROD_ID,PTL_PORTFOLIO.PORTFOLIO_NAME from MOCK_PRODUCT_DEAL inner join MOCK_TEST on MOCK_PRODUCT_DEAL.MOCK_ID = MOCK_TEST.MOCK_ID inner join PTL_PORTFOLIO on MOCK_TEST.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID where 1=1
and MOCK_PRODUCT_DEAL.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
) DD group by DD.FINPROD_ID ) EE on AA.finprodId = EE.finprodId where 1=1
and fin_product_type.TYPE_8 = #{type8,jdbcType=VARCHAR}
and PTL_PORTFOLIO.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}
and PTL_PORTFOLIO.mdate >= to_date(#{mdateStart}, 'yyyy-MM-dd')
and PTL_PORTFOLIO.mdate <= to_date(#{mdateEnd}, 'yyyy-MM-dd')
and fin_product.mdate >= to_date(#{mdateStartzc}, 'yyyy-MM-dd')
and fin_product.mdate <= to_date(#{mdateEndzc}, 'yyyy-MM-dd')
and PTL_PORTFOLIO.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})

SELECT FINPROD_ID id, FINPROD_ABBR text, FINPROD_NAME, FINPROD_MARKET_ID FROM FIN_PRODUCT
and (FINPROD_ID like concat(concat('%',#{search}),'%') or FINPROD_NAME like concat(concat('%',#{search}),'%'))
AND FINPROD_TYPE2 in
#{item}
AND FINPROD_ID = #{initValue}
